def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        import functools

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            import neo4j

            tx_args = {}
            if metadata is not None:
                tx_args["metadata"] = metadata
            if timeout is not None:
                tx_args["timeout"] = timeout

            with neo4j.Driver._execute_transaction_query_internal.func(tx_args) as tx:
                pass

            # Actually, the pattern is:
            # The decorator should return a function that, when called with a session,
            # executes the transaction using session.execute_transaction with the provided settings.

            @functools.wraps(func)
            def transactional(session, *args, **kwargs):
                import neo4j
                # Execute the transaction with the specified metadata and timeout
                return session.execute_transaction(
                    func,
                    **tx_args
                )

            # Return a wrapper that accepts a session as the first argument
            def wrapper_with_session(session, *args, **kwargs):
                return transactional(session, *args, **kwargs)

            return wrapper_with_session
        return wrapper
    return decorator
