def round_half_to_even(n):
    """

        >>> round_half_to_even(3)
        3
        >>> round_half_to_even(3.2)
        3
        >>> round_half_to_even(3.5)
        4
        >>> round_half_to_even(3.7)
        4
        >>> round_half_to_even(4)
        4
        >>> round_half_to_even(4.2)
        4
        >>> round_half_to_even(4.5)
        4
        >>> round_half_to_even(4.7)
        5

    :param n:
    :return:
    """
    import math
    floor_val = math.floor(n)
    ceil_val = math.ceil(n)
    if floor_val == ceil_val:
        return int(floor_val)
    frac_part = n - floor_val
    if abs(frac_part - 0.5) < 1e-10:
        # Tie case: round to even
        if floor_val % 2 == 0:
            return int(floor_val)
        else:
            return int(ceil_val)
    else:
        # Standard rounding: closer value
        if frac_part < 0.5:
            return int(floor_val)
        else:
            return int(ceil_val)
