def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    def get_srid(field_name):
        if field_name in srid_map:
            return int(srid_map[field_name])
        else:
            return None

    # Create the class dict
    class_dict = {
        '__module__': __name__,
        '__doc__': 'Dynamically created Point subclass %s' % name,
    }

    # Initialize attributes
    point_attrs = {}
    for i, field in enumerate(fields):
        if field.dimension == 2:
            if i == 0:
                class_dict['x'] = property(lambda self: self._point.coords[0])
            elif i == 1:
                class_dict['y'] = property(lambda self: self._point.coords[1])
        elif field.dimension == 3:
            if i == 0:
                class_dict['x'] = property(lambda self: self._point.coords[0])
            elif i == 1:
                class_dict['y'] = property(lambda self: self._point.coords[1])
            elif i == 2:
                class_dict['z'] = property(lambda self: self._point.coords[2])
        srid = field.srid
        field_name = field.name
        class_dict[field_name + '_srid'] = staticmethod(lambda: srid)

    class_dict['_srid_map'] = srid_map

    # Dynamically create the class
    cls = type(name, (), class_dict)

    if hasattr(cls, 'x') or hasattr(cls, 'y'):
        return cls

    # If no coordinates were set, just return the class
    return cls
