def parse_version(s: str) -> tuple[int, ...]:
    parts = s.split('.')
    version = []
    for part in parts:
        if part.isdigit():
            version.append(int(part))
        else:
            # Handle cases like "1.0.0-beta.1" by taking only the numeric prefix
            for ch in part:
                if ch.isdigit():
                    version.append(int(ch))
                    break
            else:
                version.append(0)
    return tuple(version)
```

