def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return cmd

    import sys
    import os

    if sys.platform == 'win32':
        # Handle Windows shebang issues
        first = cmd[0]
        if os.path.isabs(first) or os.path.exists(first):
            # Check if it's a script with shebang (e.g., Python script)
            try:
                with open(first, 'rb') as f:
                    first_line = f.readline(100)
                if first_line.startswith(b'#!'):
                    shebang = first_line[2:].strip()
                    shebang_parts = shebang.split(b' ', 1)
                    if shebang_parts:
                        interpreter = shebang_parts[0].decode('utf-8', errors='replace')
                        if interpreter:
                            rest = shebang_parts[1].decode('utf-8', errors='replace') if len(shebang_parts) > 1 else ''
                            new_cmd = [interpreter]
                            if rest:
                                new_cmd.append(rest)
                            new_cmd.append(first)
                            new_cmd.extend(cmd[1:])
                            return tuple(new_cmd)
            except (IOError, OSError):
                pass

        # If the command is a .py file, use python to execute it
        if first.lower().endswith('.py'):
            return (sys.executable,) + cmd

        # If the command is a .bat or .cmd file, it should be run with cmd.exe
        if first.lower().endswith(('.bat', '.cmd')):
            return ('cmd.exe', '/c') + cmd

    return cmd
