def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    import functools
    from collections import OrderedDict

    def decorator(func):
        cache = OrderedDict()
        maxsize_val = maxsize

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if typed:
                key = args
            else:
                key = args
            # Create a hashable key from args and kwargs
            try:
                key = (key, tuple(kwargs.items()))
            except TypeError:
                raise TypeError("Cache key must be hashable")

            now = timer()
            if key in cache:
                value, timestamp = cache[key]
                if now - timestamp <= ttl:
                    # Move to end to mark as most recently used
                    cache.move_to_end(key)
                    return value
                else:
                    # Expired, remove from cache
                    del cache[key]
            else:
                # Compute new value
                result = func(*args, **kwargs)

            # Store in cache
            cache[key] = (result, now)

            # Evict LRU items if over maxsize
            while len(cache) > maxsize_val:
                cache.popitem(last=False)

            return result

        def cache_info():
            """Return cache statistics (hits, misses, size, maxsize)."""
            # This is a simplified version; tracking hits/misses properly requires more state
            return {"size": len(cache), "maxsize": maxsize}

        def cache_clear():
            """Clear the cache."""
            cache.clear()

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear

        return wrapper

    return decorator
