def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    from collections import OrderedDict

    def decorator(func):
        cache = OrderedDict()
        hits = 0
        misses = 0
        maxsize_local = maxsize

        def wrapper(*args, **kwargs):
            nonlocal hits, misses, cache
            if typed:
                key = (args, tuple(sorted(kwargs.items())))
            else:
                if kwargs:
                    # Use a unified key that includes both positional and keyword arguments
                    key = (args, tuple(sorted(kwargs.items())))
                else:
                    key = args

            if key in cache:
                hits += 1
                # Move the entry to the end as it was just used (most recent)
                cache.move_to_end(key)
                return cache[key]
            else:
                misses += 1

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses, cache
            if typed:
                key = (args, tuple(sorted(kwargs.items())))
            else:
                if kwargs:
                    key = (args, tuple(sorted(kwargs.items())))
                else:
                    key = args

            if key in cache:
                hits += 1
                cache.move_to_end(key)
                return cache[key]
            else:
                misses += 1
                value = func(*args, **kwargs)
                cache[key] = value
                if len(cache) > maxsize_local:
                    # Remove the least recently used item
                    cache.popitem(last=False)
                return value

        def cache_info():
            return f"CacheInfo(hits={hits}, misses={misses}, maxsize={maxsize_local}, size={len(cache)})"

        def cache_clear():
            nonlocal hits, misses, cache
            hits = 0
            misses = 0
            cache.clear()

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    if callable(maxsize):
        # maxsize was passed without parentheses, e.g., @lru_cache
        func = maxsize
        maxsize = 128
        typed = False
        return decorator(func)

    return decorator
