def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        freq = {}
        min_freq = 1

        def cache_key(args, kwargs):
            if not typed:
                return args
            return args + tuple(type(a) for a in args)

        def wrapper(*args, **kwargs):
            key = cache_key(args, kwargs)
            if key in cache:
                value, frequency = cache[key]
                freq[key] = frequency + 1
                cache[key] = (value, frequency + 1)
                return value
            result = func(*args, **kwargs)
            cache[key] = (result, 1)
            freq[key] = 1
            if len(cache) > maxsize:
                # Find the least frequently used key
                lfu_key = min(cache.keys(), key=lambda k: cache[k][1])
                del cache[lfu_key]
            return result
        wrapper.cache_info = lambda: {"maxsize": maxsize, "size": len(cache)}
        wrapper.cache_clear = lambda: cache.clear()
        return wrapper
    return decorator
