def extostr(cls, e, max_level=30, max_path_level=5):
    import traceback
    import os

    # Get the exception traceback
    tb = e.__traceback__
    stack = traceback.extract_tb(tb)

    lines = [f"{type(e).__name__}: {str(e)}"]

    # Add stack frames
    if stack:
        lines.append("Stack trace:")
        for frame in stack[-max_level:]:
            filename = frame.filename
            if max_path_level is not None:
                parts = filename.replace('\\', '/').split('/')
                if len(parts) > max_path_level:
                    filename = '.../' + '/'.join(parts[-max_path_level:])
            lines.append(f"  File \"{filename}\", line {frame.lineno}, in {frame.name}")

    return "\n".join(lines)
