def integral(bins, edges):
    if len(edges) < 2:
        return 0.0

    if len(edges) != len(bins) + 1:
        raise ValueError("Number of edges should be one more than number of bins")

    total = 0.0
    for i in range(len(bins)):
        total += bins[i] * (edges[i + 1] - edges[i])

    return total
