def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        is_source = seq.get('Source')
    except (AttributeError, TypeError):
        is_source = False

    if is_source is not None:
        return False

    # Check if the sequence itself is a FillRequest
    if hasattr(seq, 'FillRequest') or isinstance(seq, dict) and 'FillRequest' in seq:
        return True

    # Check if the sequence contains at least one FillRequest
    try:
        if isinstance(seq, (list, tuple, set)):
            return any(
                (hasattr(item, 'FillRequest') or (isinstance(item, dict) and 'FillRequest' in item))
                for item in seq
            )
        elif isinstance(seq, dict):
            # If it's a dict, check if any value is a FillRequest
            return any(
                (hasattr(item, 'FillRequest') or (isinstance(item, dict) and 'FillRequest' in item))
                for item in seq.values()
            )
        else:
            # For other types, try to see if it contains a FillRequest
            return hasattr(seq, 'FillRequest') or (isinstance(seq, dict) and 'FillRequest' in seq)
    except (TypeError, AttributeError):
        return False
