    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """

    if d1 is None:
        return d2
    if d2 is None:
        return d1
    if not isinstance(d1, dict):
        return d1
    if not isinstance(d2, dict):
        return d2

    if level == 0:
        return d1

    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        else:
            val1 = d1[key]
            val2 = d2[key]
            if isinstance(val1, dict) and isinstance(val2, dict):
                sub_diff = difference(val1, val2, -1 if level == -1 else level - 1)
                if sub_diff:
                    result[key] = sub_diff
            else:
                if val1 != val2:
                    result[key] = val1
    return result
