    def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Determine which bin the coordinate falls into
        if isinstance(coord, (int, float)):
            # If it's a single number, assume it's the first (or only) axis
            idx = (coord - self.edges[0][0]) / (self.edges[0][1] - self.edges[0][0])
            if not (self.edges[0][0] <= coord < self.edges[0][1] or (coord == self.edges[0][1] and len(self.edges[0]) > 2)):
                return
            bin_idx = int(idx)
            if bin_idx < 0 or bin_idx >= self.n_bins[0]:
                return
            self.hist[bin_idx] += weight
        elif hasattr(coord, '__len__'):
            # If it's a list of coordinates
            bin_indices = []
            for i, c in enumerate(coord):
                edges = self.edges[i]
                if i == len(self.edges) - 1:
                    # Last axis
                    if not (edges[0] <= c <= edges[1]):
                        return
                    bin_idx = int((c - edges[0]) / (edges[1] - edges[0]))
                    if bin_idx == len(self.bins_per_axis[i]) - 1:
                        bin_idx = bin_idx - 1
                    if bin_idx < 0 or bin_idx >= self.n_bins[i]:
                        return
                    bin_indices.append(bin_idx)
                else:
                    # Non-last axis
                    if not (edges[0] <= c < edges[1]):
                        return
                    bin_idx = int((c - edges[0]) / (edges[1] - edges[0]))
                    if bin_idx < 0 or bin_idx >= self.n_bins[i]:
                        return
                    bin_indices.append(bin_idx)
            # Flatten the multi-dimensional index into a single index
            flat_index = 0
            for idx in bin_indices:
                flat_index = flat_index * self.n_bins[len(bin_indices) - 1] + idx
            self.hist[flat_index] += weight
