def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for schema_index, schema_item in enumerate(observer_schema):
        if isinstance(schema_item, list):
            # Recurse into nested list
            if schema_index < len(last_applied_manifest):
                if not isinstance(last_applied_manifest[schema_index], list):
                    last_applied_manifest[schema_index] = []
                if schema_index < len(response):
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[schema_index],
                        schema_item,
                        response[schema_index] if schema_index < len(response) else []
                    )
        elif isinstance(schema_item, dict):
            if schema_index < len(last_applied_manifest):
                if not isinstance(last_applied_manifest[schema_index], dict):
                    last_applied_manifest[schema_index] = {}
                if schema_index < len(response):
                    from my_utils import update_last_applied_manifest_dict_from_resp
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[schema_index],
                        schema_item,
                        response[schema_index] if schema_index < len(response) else {}
                    )
        else:
            # Scalar value
            if schema_index < len(response):
                response_value = response[schema_index]
                if schema_index >= len(last_applied_manifest):
                    last_applied_manifest.append(response_value)
                elif last_applied_manifest[schema_index] is None or last_applied_manifest[schema_index] == "":
                    last_applied_manifest[schema_index] = response_value
