        raise TypeError(f"Expected Application, got {type(app).__name__}")

    manifest = app.spec.manifest
    observer_schemas = app.spec.observer_schema

    # Ensure observer_schema is a dict
    if observer_schemas is None:
        observer_schemas = {}

