    for manifest in app.manifest:
        kind = manifest.kind
        name = manifest.metadata.name

        # Skip if a custom observer schema has already been specified
        if hasattr(app, 'observer_schema') and app.observer_schema and (kind, name) in app.observer_schema:
            continue

        default_schema = {
            "condition": {
                "type": "boolean",
                "description": "Condition for successful observation"
