def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        type_value = inventory.get('type', '')
        if type_value:
            self.spec_version = self._get_spec_version_from_type(type_value)

    errors = []
    if not isinstance(inventory, dict):
        errors.append("Inventory must be a dictionary.")
        return errors

    required_fields = ['version', 'type', 'items']
    for field in required_fields:
        if field not in inventory:
            errors.append(f"Missing required field: {field}")

    if not errors:
        # Validate structure
        if not isinstance(inventory['items'], list):
            errors.append("'items' must be a list.")

        for index, item in enumerate(inventory['items']):
            if not isinstance(item, dict):
                errors.append(f"Item at index {index} is not a dictionary.")
                continue

            if 'name' not in item:
                errors.append(f"Item at index {index} is missing 'name' field.")

            if 'quantity' in item and not isinstance(item['quantity'], int):
                errors.append(f"'quantity' in item at index {index} must be an integer.")

    return errors
