def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        if "type" in inventory:
            spec_version = inventory["type"]
            if spec_version in self.SUPPORTED_SPEC_VERSIONS:
                self.spec_version = spec_version
            else:
                self.errors.append(f"Invalid specification version: {spec_version}")
        else:
            self.errors.append("No type value found in inventory")

    if "name" not in inventory:
        self.errors.append("Inventory is missing required 'name' field")

    if "attributes" not in inventory:
        self.errors.append("Inventory is missing required 'attributes' field")
    else:
        attributes = inventory["attributes"]
        if not isinstance(attributes, dict):
            self.errors.append("'attributes' must be a dictionary")
        else:
            for key, value in attributes.items():
                if key not in self.ATTRIBUTE_WHITELIST:
                    self.errors.append(f"Attribute '{key}' is not allowed")

