        # Validate the files
        files = fixity.get("files")
        if not isinstance(files, list):
            raise ValueError("Files must be a list")

        # Check that each entry in files is valid
        for file_info in files:
            if not isinstance(file_info, dict):
                raise ValueError("Each file in the fixity block must be a dictionary")

            required_file_fields = {"name", "hash", "size"}
            if not required_file_fields.issubset(file_info.keys()):
                raise ValueError(f"File entry missing required fields: {required_file_fields - set(file_info.keys())}")

            name = file_info.get("name")
            if not isinstance(name, str) or not name:
                raise ValueError("File name must be a non-empty string")

            hash_value = file_info.get("hash")
            if not isinstance(hash_value, str) or not hash_value:
                raise ValueError("File hash must be a non-empty string")

            size = file_info.get("size")
            if not isinstance(size, int) or size <= 0:
                raise ValueError("File size must be a positive integer")

            # Check that the file is in the manifest
            if name not in manifest_files:
