def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = " " * indent
    if hasattr(self, 'items'):
        items = self.items()
    else:
        items = []

    result = []
    for key, value in items:
        if isinstance(value, (dict, list, tuple, set)):
            if debug:
                value_repr = value.pretty(indent + len(indent_str) + 1, debug)
            else:
                value_repr = value.pretty(indent + len(indent_str) + 1)
            result.append(f"{indent_str}{key}: {value_repr}")
        else:
            result.append(f"{indent_str}{key}: {value}")

    if result:
        return "\n".join(result)
    else:
        return str(self)
