    def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        from sympy.logic.boolalg import And, Or, Not, BooleanTrue, BooleanFalse, Equality, Implies, Xor, Nand, Nor, Equivalent
        from sympy.core.relational import Relational
        from sympy.core.sympify import sympify

        exprs = list(args)

        # First pass: apply absorption and negative absorption
        changed = True
        while changed:
            changed = False
            new_exprs = []
            # Check all pairs
            for i, e1 in enumerate(exprs):
                for j, e2 in enumerate(exprs):
                    if i == j:
                        continue
                    if not isinstance(e1, (And, Or)) or not isinstance(e2, (And, Or)):
                        continue
                    # Check absorption: A & (A | B) = A or A | (A & B) = A
                    # Check negative absorption: A & (~A | B) = A & B or A | (~A & B) = A | B
                    try:
                        result = self._absorb_pair(e1, e2)
                        if result is not None:
                            changed = True
                            # Replace both expressions with result
                            exprs = [x for k, x in enumerate(exprs) if k not in (i, j)]
                            exprs.append(result)
                            break
                    except Exception:
                        pass
                if changed:
                    break
        # Return the simplified list
        return exprs

    def _absorb_pair(self, a, b):
        """
        Try to apply absorption or negative absorption between two boolean expressions a and b.
        Returns the simplified expression if applicable, else None.
        """
        from sympy.logic.boolalg import And, Or, Not
        from sympy import simplify_logic

        # Check absorption: A & (A | B) = A or A | (A & B) = A
        # Also negative absorption: A & (~A | B) = A & B or A | (~A & B) = A | B

        # Let's try to see if we can match patterns

        # Pattern 1: a is And, b is Or
        if isinstance(a, And) and isinstance(b, Or):
            a_args = list(a.args)
            b_args = list(b.args)
            # Check if any arg in a is in b or its negation is in b
            for i, x in enumerate(a_args):
                # Absorption: if x is in b
                if any(sympify(x) == y for y in b_args):
                    return x  # A & (A | B) = A
                # Negative absorption: if ~x is in b
                neg_x = Not(x)
                if any(neg_x == y for y in b_args):
                    # A & (~A | B) = A & B
                    # B is the args in b except ~x
                    other_args = [z for z in b_args if z != neg_x]
                    if other_args:
                        return And(x, *other_args)
                    else:
                        return x
        # Pattern 2: a is Or, b is And
        elif isinstance(a, Or) and isinstance(b, And):
            a_args = list(a.args)
            b_args = list(b.args)
            for i, x in enumerate(a_args):
                # Absorption: A | (A & B) = A
                if any(sympify(x) == y for y in b_args):
                    return x
                # Negative absorption: A | (~A & B) = A | B
                neg_x = Not(x)
                if any(neg_x == y for y in b_args):
                    other_args = [z for z in b_args if z != neg_x]
                    if other_args:
                        return Or(x, *other_args)
                    else:
                        return x
        elif isinstance(b, And) and isinstance(a, Or):
            return self._absorb_pair(b, a)
        elif isinstance(b, Or) and isinstance(a, And):
            return self._absorb_pair(b, a)

        return None
