    def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        args = list(args)
        for i, a in enumerate(args):
            for j, b in enumerate(args):
                if i == j:
                    continue
                if isinstance(a, And) and isinstance(b, Or):
                    if a.args[0].equals(b.args[0]):
                        # A & (A | B) = A
                        args[i] = a.args[0]
                        args[j] = None
                elif isinstance(a, Or) and isinstance(b, And):
                    if a.args[0].equals(b.args[0]):
                        # A | (A & B) = A
                        args[i] = a.args[0]
                        args[j] = None
                elif isinstance(a, And) and isinstance(b, Or):
                    for arg in a.args:
                        if arg.equals(~b.args[0]):
                            # A & (~A | B) = A & B
                            args[i] = And(*list(a.args) + [b.args[1]]) if len(a.args) > 1 else a.args[0]
                            args[j] = None
                elif isinstance(a, Or) and isinstance(b, And):
                    for arg in a.args:
                        if arg.equals(~b.args[0]):
                            # A | (~A & B) = A | B
                            args[i] = Or(*list(a.args) + [b.args[1]]) if len(a.args) > 1 else a.args[0]
                            args[j] = None
        return [a for a in args if a is not None]
