def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if pieces["error"]:
        raise ValueError(pieces["error"])

    if pieces["dirty"]:
        # Adds .dev0 locally, and .dirty if there are local changes.
        pieces["closest-tag"] = pieces.get("closest-tag") or "0.0.0"
        if style == "pep440":
            pieces["rendered"] = pieces["closest-tag"] + ".dev0"
        else:
            pieces["rendered"] = pieces["closest-tag"] + ".0.dev0"
        pieces["rendered"] += "+dirty"
    else:
        if style == "pep440":
            # If we don't have a version, use 0.0.0
            if "closest-tag" in pieces and pieces["closest-tag"]:
                # If we are at the closest tag
                if pieces["distance"] == 0:
                    pieces["rendered"] = pieces["closest-tag"]
                else:
                    # We are past the closest tag, so we need to add dev
                    pieces["rendered"] = pieces["closest-tag"] + ".dev" + str(pieces["distance"])
            else:
                pieces["rendered"] = "0.0.0.dev" + str(pieces["distance"]) if pieces["distance"] else "0.0.0"
        else:
            # For git describe style or other fallback
            if "closest-tag" in pieces and pieces["closest-tag"]:
                if pieces["distance"] == 0:
                    pieces["rendered"] = pieces["closest-tag"]
                else:
                    pieces["rendered"] = pieces["closest-tag"] + ".0.dev" + str(pieces["distance"])
            else:
                pieces["rendered"] = "0.0.0.dev" + str(pieces["distance"]) if pieces["distance"] else "0.0.0"

    # Check for archive tag
    if "archive" in pieces and pieces["archive"]:
        pieces["rendered"] = pieces["archive"]

    return pieces["rendered"]
