def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # If commands is a string, convert to a list
    if isinstance(commands, str):
        commands = [commands]
    elif isinstance(commands, (list, tuple)):
        commands = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    # If args is a string, convert to a list
    if isinstance(args, str):
        args = args.split()
    elif isinstance(args, (list, tuple)):
        args = list(args)
    else:
        args = []

    # Build the full command list
    cmd_list = commands + args

    # Combine environment if provided
    if env:
        env = os.environ.copy()
        env.update(env)
    else:
        env = os.environ.copy()

    # Prepare subprocess kwargs
    kwargs = dict(
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE if hide_stderr else None,
    )

    # Run the command
    try:
        process = subprocess.Popen(cmd_list, **kwargs)
        stdout, stderr = process.communicate()

        if verbose:
            import sys
            print(f"Command: {' '.join(cmd_list)}")
            if stdout:
                sys.stdout.buffer.write(stdout)
            if stderr and not hide_stderr:
                sys.stderr.buffer.write(stderr)

        return process.returncode if process.returncode == 0 else False

    except Exception as e:
        if verbose:
            import sys
            sys.stderr.write(f"Error running command: {str(e)}\n")
        return False
