def next_version(version):
    # Split the version string into parts
    if version:
        parts = version.split('.')
        # Find the last non-zero part to increment
        new_parts = []
        for i, part in enumerate(parts):
            if i < len(parts) - 1:
                new_parts.append(part)
            else:
                # This is the last part, increment it
                new_parts.append(str(int(part) + 1))
        # If there are zero-prefixed parts before the last, we need to ensure
        # that the zeros are preserved or handled correctly.
        # But the simplest and most robust interpretation is to just increment
        # the last numeric component and preserve the rest exactly as they are.
        return '.'.join(new_parts)
    else:
        return "1"

