        # Example: 000, 01, 1
        if re.fullmatch(r'0*\d+', version):
            # Remove leading zeros, convert to int, increment, then
            # re-add leading zeros to match original pattern length
            num = int(version)
            next_num = num + 1
            # Preserve leading zeros: if original had leading zeros, pad to same length
            if version[0] == '0' and len(version) > 1:
                return str(next_num).zfill(len(version))
            else:
                return str(next_num)
        else:
            # If it's a standard version, just increment the last numeric part
            # For simplicity, handle common case where it's a number as a string
            try:
                num = int(version)
                return str(num + 1)
            except ValueError:
                # If not a simple number, return as-is or raise
                raise ValueError(f"Unsupported version format: {version}")
