    def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        root_inventory_digests = self._get_root_inventory_digests()
        mismatched_digests = {}

        for version_dir in version_dirs:
            # Check if version inventory exists
            version_inventory_path = os.path.join(self._repository_path, version_dir, "inventory")
            if not os.path.exists(version_inventory_path):
                self._log_warning(f"No inventory found for version directory: {version_dir}")
                continue

            # Read version inventory
            try:
                with open(version_inventory_path, 'r') as f:
                    version_inventory = json.load(f)
            except (json.JSONDecodeError, IOError) as e:
                self._log_error(f"Error reading inventory for version directory {version_dir}: {e}")
                continue

            # Extract digests from version inventory
            for item_name, item_data in version_inventory.items():
                if isinstance(item_data, dict) and "digest" in item_data:
                    digest = item_data["digest"]
                    if item_name in root_inventory_digests:
                        root_digest = root_inventory_digests[item_name]
                        if digest != root_digest:
                            # Record the mismatch
                            if item_name not in mismatched_digests:
                                mismatched_digests[item_name] = set()
                            mismatched_digests[item_name].add(digest)

        self._mismatched_digests = mismatched_digests
