def find_path_type(path):
    try:
        if not os.path.exists(path):
            return "path does not exist"
        if os.path.isdir(path):
            # Check for 0=root marker in the directory
            if os.path.exists(os.path.join(path, "0=root")):
                return "root"
            # Check for 0=object marker
            if os.path.exists(os.path.join(path, "0=object")):
                return "object"
            # Check if it's a directory that looks like it might contain OCFL content
            # Without specific 0= file, it might be an object directory if it has inventory
            inventories = [f for f in os.listdir(path) if f.endswith("inventory.json")]
            if inventories:
                return "object"
            # Check if it's a version directory with 0= file
            entries = [f for f in os.listdir(path) if f.startswith("0=")]
            if entries:
                if "0=root" in entries:
                    return "root"
                if "0=object" in entries:
                    return "object"
            return "directory (not OCFL)"
        elif os.path.isfile(path):
            # Check if it's an inventory file
            if os.path.basename(path) == "inventory.json":
                return "file"
            return "file"
        else:
            return "unknown"
    except Exception as e:
        return f"error: {str(e)}"

