def find_path_type(path):
    import os
    from stat import S_ISDIR, S_ISREG
    from glob import glob

    # First, check if path exists
    if not os.path.exists(path):
        return 'path does not exist'

    # Check if it's a file
    if os.path.isfile(path):
        return 'file'

    # Check if it's a directory
    if os.path.isdir(path):
        # Look for 0=* Namaste files in the path
        namaste_files = glob(os.path.join(path, '0=*'))

        # Check for inventory files
        inventory_files = glob(os.path.join(path, 'inventory.json'))

        if len(namaste_files) == 0 and len(inventory_files) == 0:
            # Check if this is a storage root by looking for objects directory
            if os.path.isdir(os.path.join(path, 'objects')):
                return 'root'
            return 'directory'
        elif len(namaste_files) > 0 and len(inventory_files) > 0:
            return 'object'
        elif len(namaste_files) > 0:
            # Has namaste files but no inventory, might be a root with objects
            if os.path.isdir(os.path.join(path, 'objects')):
                return 'root'
            return 'object'
        else:
            # Has inventory but no namaste files
            if os.path.isdir(os.path.join(path, 'objects')):
                return 'root'
            return 'object'

    return 'unknown'
