                old_children = old_value.value
                new_children = value.value
                merged_children = deep_merge_nodes(list(old_children) + list(new_children))
                # Create a new MappingNode with merged children
                merged[key.value] = type(old_value)(old_value.tag, merged_children, flow_style=old_value.flow_style, start_mark=old_value.start_mark, end_mark=value.end_mark, lc=old_value.lc, comment=old_value.comment)
            else:
                # Last value wins
                merged[key.value] = value
        else:
            merged[key.value] = value
    # Reconstruct the list of tuples, preserving the structure
    result = []
    for key_value, value in merged.items():
        # We need to find the original key node that had this value
        original_key = next((k for k, v in nodes if v is value or (hasattr(k, 'value') and k.value == key_value)), None)
        if original_key is None:
            # Create a new key node if not found (should not happen normally)
            original_key = key
        result.append((original_key, value))
    return result
