def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed = {}
    remaining = list(unparsed_arguments)
    for name, parser in subparsers.items():
        args, remaining_args = parser.parse_known_args(remaining)
        if not args == parser.parse_known_args([])[0]:  # Only include if something was parsed
            parsed[name] = args
        # Update remaining to be the args not consumed by this parser
        remaining = remaining_args
    return (parsed, remaining)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_namespaces = {}
    remaining_arguments = []
    claimed_indices = [False] * len(unparsed_arguments)
    for name, subparser in subparsers.items():
        try:
            namespace, new_remaining = subparser.parse_known_args(unparsed_arguments)
        except SystemExit:
            continue
        parsed_namespaces[name] = namespace
        for arg in new_remaining:
            for i, arg_from_original in enumerate(unparsed_arguments):
                if arg == arg_from_original and not claimed_indices[i]:
                    claimed_indices[i] = True
                    break
    for i, claimed in enumerate(claimed_indices):
        if not claimed:
            remaining_arguments.append(unparsed_arguments[i])
    return parsed_namespaces, remaining_arguments

