def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        base_str = alphabet[0]
    else:
        base_str = ""
        negative = number < 0
        number = abs(number)
        while number > 0:
            number, remainder = divmod(number, len(alphabet))
            base_str = alphabet[remainder] + base_str
        if negative:
            base_str = "-" + base_str

    if padding is not None:
        if len(base_str) < padding:
            base_str = "0" * (padding - len(base_str)) + base_str if not base_str.startswith("-") else "-" + "0" * (padding - len(base_str) - 1) + base_str[1:]

    return base_str
