def split(s, platform='this'):
    if platform == 'this':
        platform = 0 if os.name in ('nt', 'os2') else 1
    if platform == 1:
        # POSIX style: remove quotes, keep escaped chars
        chars = []
        in_quote = None
        escape = False
        for ch in s:
            if escape:
                chars.append(ch)
                escape = False
                continue
            if ch == '\\':
                escape = True
                continue
            if ch in ('"', "'"):
                if in_quote is None:
                    in_quote = ch
                elif in_quote == ch:
                    in_quote = None
                continue
            if in_quote is None and ch.isspace():
                if chars:
                    yield ''.join(chars)
                    chars = []
                continue
            chars.append(ch)
        if chars:
            yield ''.join(chars)
    elif platform == 0:
        # Windows style: more complex quoting rules
        yield from re.split(r'(?<!\\)\s+', s.strip())
    else:
        raise ValueError("Invalid platform value")

