import re
def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1

    if platform == 1:
        # POSIX: split on whitespace, respect quotes
        tokens = []
        current = ''
        quote_char = None
        i = 0
        while i < len(s):
            c = s[i]
            if quote_char is None:
                if c in ('"', "'"):
                    quote_char = c
                    i += 1
                elif c.isspace():
                    if current:
                        tokens.append(current)
                        current = ''
                    i += 1
                else:
                    current += c
                    i += 1
            else:
                if c == quote_char:
                    quote_char = None
                    if current:
                        tokens.append(current)
                        current = ''
                    i += 1
                else:
                    current += c
                    i += 1
        if current:
            tokens.append(current)
        if quote_char is not None:
            # Unterminated quote
            tokens.append(current)
        return tokens
    elif platform == 0:
        # Windows: split on whitespace, ignore quotes
        return s.split()
    else:
        raise ValueError(f"Unknown platform value: {platform}")

