    if ignored is None:
        return ""

    try:
        # Get the list of ignored files using git
        output = subprocess.check_output(["git", "status", "--ignored", "--porcelain"], stderr=subprocess.STDOUT, text=True)
    except subprocess.CalledProcessError:
        return ""

    ignored_files = []
    for line in output.splitlines():
        if line.startswith('!! '):
            filename = line[3:].strip()
            if filename:
                ignored_files.append(filename)

    # Sort the list
    ignored_files.sort()

    # Join filenames with comma as separator
    return ",".join(ignored_files)
