def is_local(host):
    try:
        # Check if the host is localhost
        if host in ("localhost", "127.0.0.1", "::1"):
            return True
        # Try to resolve the host to see if it's a local address
        import socket
        addr_infos = socket.getaddrinfo(host, None)
        for family, socktype, proto, canonname, sockaddr in addr_infos:
            ip = sockaddr[0]
            if ip in ("127.0.0.1", "::1"):
                return True
            # Check if it's a local IP address (127.x.x.x for IPv4 or ::1 for IPv6)
            if family == socket.AF_INET and ip.startswith("127."):
                return True
        return False
    except (socket.socket.gaierror, socket.error):
        return False
