import subprocess
def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]

    # Build the full command as a list
    cmd = list(commands) + list(args)

    # Prepare the environment
    if env is not None:
        my_env = env
    else:
        my_env = None

    # Prepare the keyword arguments for subprocess
    kwargs = {}
    if cwd is not None:
        kwargs['cwd'] = cwd
    if env is not None:
        kwargs['env'] = env

    # Handle stderr
    if hide_stderr:
        kwargs['stderr'] = subprocess.DEVNULL

    # Capture output
    stdout = None
    stderr = None

    try:
        if verbose:
            print("Running: '{}'".format(' '.join(cmd)))

        # Run the command
        result = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            **kwargs
        )

        stdout = result.stdout
        stderr = result.stderr

        if result.returncode != 0:
            if verbose:
                print("Command failed with return code {}".format(result.returncode))
                if stderr:
                    print("Stderr: {}".format(stderr.decode('utf-8', errors='strict')))
            raise subprocess.CalledProcessError(result.returncode, cmd, stdout=stdout, stderr=stderr)
    except subprocess.CalledProcessError as e:
        raise
    except Exception as e:
        raise

    return stdout, stderr
