def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    for child, p, parent in graph:
        if p == prop:
            roots.add(child)
    # Now, find nodes that are not parents of any other node under the given prop
    roots = roots.difference(set(graph.objects(None, prop)))
    return roots
