        try:
            with open(filename, 'r') as f:
                content = f.read()

            # Simple YAML-like parsing (for demonstration purposes)
            # In a real application, you'd use a proper YAML parser
            config = {}
            for line in content.split('\n'):
                line = line.strip()
                if line and not line.startswith('#') and ':' in line:
                    key, value = line.split(':', 1)
                    config[key.strip()] = value.strip()

            configs[filename] = config

        except Exception as e:
            errors.append(logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Error loading configuration file '{filename}': {str(e)}",
                args=(),
                exc_info=(type(e), e, e.__traceback__)
            ))

    # Apply environment variable resolution if requested
    if resolve_env and configs:
        for filename, config in configs.items():
            if isinstance(config, dict):
                resolved_config = {}
                for key, value in config.items():
                    if isinstance(value, str) and value.startswith('${') and value.endswith('}'):
                        env_var = value[2:-1]
                        resolved_value = os.getenv(env_var, value)
                        resolved_config[key] = resolved_value
                    else:
                        resolved_config[key] = value
                configs[filename] = resolved_config

    return configs, errors
