import logging
import os
import yaml
import json
import re


def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    config_dict = {}
    error_logs = []

    if overrides is None:
        overrides = {}

    # Simple validation ensure: config must be a dict
    def validate_config(config):
        if not isinstance(config, dict):
            raise ValueError("Configuration must be a dictionary")
        return config

    # Resolve environment variables in strings
    def resolve_env_vars(value):
        if resolve_env and isinstance(value, str):
            # Pattern to detect environment variable references like $VAR_NAME or ${VAR_NAME}
            pattern = r'\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?'

            def replace_match(match):
                var_name = match.group(1)
                return os.environ.get(var_name, match.group(0))  # If not found, keep original
            return re.sub(pattern, replace_match, value)
        elif isinstance(value, dict):
            return {key: resolve_env_vars(val) for key, val in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(item) for item in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                # Determine the file type by extension
                ext = os.path.splitext(filename)[1].lower()
                if ext in ['.yml', '.yaml']:
                    raw_config = yaml.safe_load(f)
                elif ext == '.json':
                    raw_config = json.load(f)
                else:
                    # Try YAML as default or fallback
                    raw_config = yaml.safe_load(f)

            # Apply overrides if any
            if overrides and filename in overrides:
                def deep_merge(base, override):
                    """Recursively merge override into base"""
                    if isinstance(base, dict) and isinstance(override, dict):
                        merged = base.copy()
                        for key, value in override.items():
                            if key in base:
                                merged[key] = deep_merge(base[key], value)
                            else:
                                merged[key] = value
                        return merged
                    else:
                        return override
                raw_config = deep_merge(raw_config, overrides[filename])

            # Resolve environment variables
            if resolve_env:
                raw_config = resolve_env_vars(raw_config)

            # Validate
            validated_config = validate_config(raw_config)
            config_dict[filename] = validated_config

        except Exception as e:
            logger = logging.getLogger(__name__)
            record = logger.error(f"Failed to load configuration file {filename}: {e}")
            error_logs.append(record)

    return (config_dict, error_logs)

