    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if ticks < 0 or ticks >= 86400000000000:
            raise ValueError("Ticks out of bounds: must be in range [0, 86400000000000)")

        total_seconds = ticks // 1000000000
        microseconds = (ticks % 1000000000) // 1000

