    checks = []
    if not tentative:
        checks.append(iface.providedBy(candidate))
    invalidAttrs = []
    for name in iface.__names__:
        if not hasattr(candidate, name):
            invalidAttrs.append(name)
    invalidMethods = []
    for name in iface.__names__:
        if hasattr(candidate, name):
            method = getattr(candidate, name)
            expected = getattr(iface, name)
            if not callable(expected) and callable(method):
