            if callable(expected):
                try:
                    args = expected.__code__.co_varnames[:expected.__code__.co_argcount]
                    cargs = method.__code__.co_varnames[:method.__code__.co_argcount]
                    if args and args != ['self'] and cargs != args:
                        invalidMethods.append(name)
                except AttributeError:
                    pass
    if not invalidAttrs and not invalidMethods and all(checks):
        return True
    errors = []
    for attr in invalidAttrs:
        errors.append("Attribute %r not found" % (attr,))
    for method in invalidMethods:
        errors.append("Method %r invalid" % (method,))
    if not tentative:
        for check in checks:
            if not check:
                errors.append("Candidate does not claim to provide interface")
    if len(errors) == 1:
        raise Invalid(errors[0])
