def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    required_metatype = None
    for base in bases:
        base_metatype = base.__class__
        if required_metatype is None:
            required_metatype = base_metatype
        else:
            if issubclass(required_metatype, base_metatype):
                required_metatype = base_metatype
            elif issubclass(base_metatype, required_metatype):
                pass
            else:
                raise TypeError("@x is a meta-class derived from a class which is not a metaclass of any base class")
    if explicit_mc is not None:
        if required_metatype is None:
            required_metatype = explicit_mc
        else:
            if issubclass(explicit_mc, required_metatype):
                required_metatype = explicit_mc
            elif not issubclass(required_metatype, explicit_mc):
                raise TypeError("metatype %s is not a subtype of type %s of meta-type"
                                % (explicit_mc.__name__, required_metatype.__name__))
    if required_metatype is None:
        required_metatype = type
    return required_metatype
