    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclasses = set([type(base) for base in bases])
    if explicit_mc is not None:
        metaclasses.add(explicit_mc)
    if not metaclasses:
        return type
    common_mc = None
    for mc in metaclasses:
        if common_mc is None:
            common_mc = mc
        else:
            if not issubclass(mc, common_mc):
                if not issubclass(common_mc, mc):
                    raise TypeError("multiple bases have instance lay-out conflict")
                common_mc = mc
    return common_mc
