def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, return it
    if explicit_mc is not None:
        return explicit_mc

    # Find the metaclass among the bases
    # The metaclass is the most derived class among the metaclasses of the bases
    metaclasses = set()
    for base in bases:
        mc = type(base)
        metaclasses.add(mc)

    # Find the most derived metaclass
    most_derived = None
    for mc in metaclasses:
        if most_derived is None:
            most_derived = mc
        else:
            # Check if mc is a subclass of most_derived
            if issubclass(mc, most_derived):
                most_derived = mc

    return most_derived
