def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if len(self._data) == 0:
        raise KeyError
    if len(self._freq) == 0:
        return self._data.popitem(last=False)
    for freq in self._freq:
        items = self._freq[freq]
        if len(items) > 0:
            item = items.pop()
            del self._data[item]
            if len(items) == 0:
                del self._freq[freq]
            return item, self._data[item]
