    def fromutc(self, dt):
        if dt.tzinfo is not self:
            raise ValueError("dt.tzinfo is not self")

        # First, we calculate the UTC datetime, assuming we're in the standard
        # offset.
        utc_dt = dt - self.utcoffset(dt)

        # For LMT offsets, we're done
        if self._utcoffset is self._standard_offset:
            return utc_dt.replace(tzinfo=self)

        # Now, we calculate the UTC datetime, assuming we're in the daylight
        # saving time offset.
        dst_utc_dt = dt - self._dst(datetime)

        # If the two are the same, then we know we're not in a transition, and
        # we can just return the UTC datetime
        if utc_dt == dst_utc_dt:
            return utc_dt.replace(tzinfo=self)

        # If it's the wrong DST state, it needs to be toggled
        if self._is_dst(utc_dt) != self._is_dst(dst_utc_dt):
            return dst_utc_dt.replace(tzinfo=self)

        # Now, we need to check which one is chronologically later
        if utc_dt < dst_utc_dt:
            return utc_dt.replace(tzinfo=self)
        else:
            return dst_utc_dt.replace(tzinfo=self)
