def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check if it's a public message request
    if isinstance(request, str):
        request = request.strip()

    # Check for public message structure (list of messages)
    if isinstance(request, list) and len(request) > 0:
        # Check if the first element is a dictionary with 'message' key
        first_item = request[0]
        if isinstance(first_item, dict):
            if 'message' in first_item or 'author' in first_item or 'activity' in first_item:
                return "public_message"

    # Check for private message structure
    if isinstance(request, dict):
        if 'message' in request and ('recipient' in request or 'to' in request):
            return "private_message"
        if 'content' in request and 'type' in request:
            # Could be a legacy payload
            return "legacy"

    # If none of the above, check if it's a legacy payload
    if isinstance(request, dict) and 'payload' in request:
        return "legacy"

    return "unknown"
