            body = request.body
            if body:
                try:
                    import json
                    data = json.loads(body)
                    if isinstance(data, dict):
                        # Check for common matrix-related keys
                        matrix_keys = ['matrix', 'event', 'room', 'user', 'idem', 'auth']
                        for key in matrix_keys:
                            if key in data:
                                return True
                except (json.JSONDecodeError, AttributeError, ValueError):
                    pass

    except Exception:
