def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    document = document.strip()
    if document.startswith('{'):
        # New JSON format
        return json.loads(document)
    else:
        # Old XRD format (XML)
        from lxml import etree
        root = etree.fromstring(document)
        subject = root.find('.//{urn:xmpp:xrd:1.0:subject}subject')
        if subject is None:
            return {}
        aliases = []
        for alias in root.findall('.//{urn:xmpp:xrd:1.0:subject}alias'):
            aliases.append(alias.text)
        links = []
        for xrd_alias in root.findall('.//{urn:xmpp:xrd:1.0:subject}alias'):
            pass  # Not needed, we just need aliases from the whole doc

        # Find all alias elements in the document
        aliases = []
        for alias in root.findall('.//{urn:xmpp:xrd:1.0:subject}alias'):
            aliases.append(alias.text)

        # Find all links
        for link in root.findall('.//{urn:xmpp:xrd:1.0:subject}link'):
            rel = link.get('rel')
            href = link.get('href')
            if rel is not None and href is not None:
                links.append({"rel": rel, "href": href})

        result = {
            "subject": subject.text,
            "aliases": aliases,
            "links": links
        }
        return result
