def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree

    # Try JSON format first
    try:
        json_data = json.loads(document)
        # Check if it's a valid webfinger JSON response
        if "links" in json_data:
            result = {}
            for link in json_data["links"]:
                if link.get("rel") == "http://webfinger.net/rel/profile":
                    result["url"] = link["href"]
                elif link.get("rel") == "http://diaspora.org/relay":
                    result["relay"] = link["href"]
                elif link.get("rel") == "magic-land" or link.get("rel") == "http://diaspora.org/relay":
                    # This might be a specific relay identifier
                    result["relay"] = link.get("href")
            if "subject" in json_data:
                result["subject"] = json_data["subject"]
            return result
    except (json.JSONDecodeError, KeyError):
        pass

    # Try XRD format
    try:
        root = ElementTree.fromstring(document)
        result = {}
        subjects = root.findall('.//{urn:xmpp:skaps/xrd:1.0}subject')
        for subject in subjects:
            rel_id = subject.get('rel')
            if rel_id == 'http://webfinger.net/rel/profile':
                result["subject"] = subject.text
            aliases = subject.findall('.//{urn:xmpp:skaps/xrd:1.0}alias')
            for alias in aliases:
                if alias.text:
                    result["subject"] = alias.text
                    break
        aliases = root.findall('.//{urn:xmpp:skaps/xrd:1.0}alias')
        for alias in root:
            if alias.tag == "{urn:xmpp:skaps/xrd:1.0}alias":
                result["subject"] = alias.text
                break
        # XRD may also contain rel elements
        rels = root.findall('.//{urn:xmpp:skaps/xrd:1.0}entity')
        return result
    except ElementTree.ParseError:
        pass

    raise ValueError("Unable to parse webfinger document")
