def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.

    Args:
        handle: The handle (e.g., "user@domain.com") to look up.

    Returns:
        The webfinger document as a string, or None if retrieval fails.
    """
    import requests
    import json

    if not handle or not handle.isascii():
        return None

    if not handle.contains('@'):
        return None

    handle_parts = handle.split('@')
    if len(handle_parts) != 2:
        return None

    handle, domain = handle_parts

    if not domain or not domain.isascii():
        return None

    # RFC 7033: .well-known/webfinger?resource=acct:user@domain
    base_url = f"https://{domain}/.well-known/webfinger"
    resource = f"acct:{handle}@{domain}"
    params = {"resource": resource}

    try:
        response = requests.get(base_url, params=params, timeout=10, allow_redirects=True)

        if response.status_code == 200:
            # Try to get the content type
            content_type = response.headers.get("Content-Type", "")

            # Check if the response is actually a webfinger document
            # Webfinger responses should be JSON (application/jrd+json)
            if "json" in content_type.lower():
                return response.text
            else:
                # Some servers return JSON without proper content type
                try:
                    response.json()
                    return response.text
                except:
                    return None
        else:
            return None
    except:
        return None
