def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if '@' not in handle:
        raise ValueError("Invalid Diaspora handle: must contain '@'")

    domain = handle.split('@')[1]
    webfinger_url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"

    request = urllib.request.Request(webfinger_url)
    request.add_header('User-Agent', 'Diaspora Client')

    try:
        with urllib.request.urlopen(request) as response:
            data = response.read()
            content_type = response.getheader('Content-Type')

            if content_type and content_type.startswith('application/json'):
                return json.loads(data.decode('utf-8'))
            elif content_type and content_type.startswith('text/plain'):
                webfinger_data = yaml.safe_load(data.decode('utf-8'))
                return webfinger_data
            else:
                # Try to detect based on content
                try:
                    return json.loads(data.decode('utf-8'))
                except json.JSONDecodeError:
                    return yaml.safe_load(data.decode('utf-8'))

    except Exception as e:
        raise ConnectionError(f"Failed to retrieve webfinger document for {handle}: {e}")
