def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' not in parser_dict:
        return parser_dict

    include_value = parser_dict.pop('include')
    if isinstance(include_value, str):
        include_value = [include_value]
    if not isinstance(include_value, (list, tuple)):
        raise ValueError("Include value must be a string or a list of strings")

    included_dicts = []
    for include_path in include_value:
        if not isinstance(include_path, str):
            raise ValueError("Include path must be a string")
        try:
            with open(include_path, 'r') as f:
                included_dict = yaml.load(f, Loader=yaml.FullLoader)
                if not isinstance(included_dict, dict):
                    raise ValueError("Included file must contain a dictionary")
                included_dicts.append(included_dict)
        except Exception as e:
            raise FileNotFoundError(f"Could not include '{include_path}': {e}")

    merged = parser_dict.copy()
    for included_dict in included_dicts:
        merged.update(included_dict)

    return merged
```

