def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for key, value in parser_dict.items():
        if isinstance(value, dict) and "include" in value:
            if isinstance(value["include"], str):
                included_dict = self._load_spec_file(value["include"])
                value.pop("include")
                value.update(included_dict)
            elif isinstance(value["include"], list):
                included_dict = {}
                for file_path in value["include"]:
                    temp_dict = self._load_spec_file(file_path)
                    included_dict.update(temp_dict)
                value.pop("include")
                value.update(included_dict)
