import os

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec_file = os.path.join(plugin_dir, "plugin_spec.java")
    if not os.path.exists(plugin_spec_file):
        return {}

    with open(plugin_spec_file, 'r') as f:
        content = f.read()

    # Extract the public static final fields
    properties = {}
    for line in content.splitlines():
        line = line.strip()
        if line.startswith("public static final"):
            parts = line.split()
            if len(parts) >= 4 and parts[4].endswith(";"):
                # Remove trailing semicolon and type info
                # Assume format: public static final String key_name = "value";
                # We need to handle different types
                if parts[3] == "String":
                    # Extract key and value
                    key_val = parts[4].rstrip(";")
                    if '=' in key_val:
                        key, value = key_val.split('=', 1)
                        properties[key.strip()] = value.strip().strip('\"')
                elif parts[3] == "int":
                    key_val = parts[4].rstrip(";")
                    if '=' in key_val:
                        key, value = key_val.split('=', 1)
                        properties[key.strip()] = int(value.strip())
                elif parts[3] == "boolean":
                    key_val = parts[4].rstrip(";")
                    if '=' in key_val:
                        key, value = key_val.split('=', 1)
                        value = value.strip()
                        properties[key.strip()] = (value.lower() == 'true')

    return properties
