import os
import yaml


def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_file = os.path.join(plugin_dir, 'plugin_spec.yaml')
    if not os.path.exists(spec_file):
        return {}

    with open(spec_file, 'r') as f:
        try:
            spec_dict = yaml.safe_load(f)
        except yaml.YAMLError as e:
            return {}

    if not isinstance(spec_dict, dict):
        return {}

    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            elif isinstance(v, list):
                # For lists, we just keep them as values, not flattening further as per typical "flat dict" interpretation
                # where the list becomes the value. If you need list elements flattened, you'd need more logic.
                # The prompt says "flat dict", usually meaning keys are dot-separated and values are scalars/lists.
                items.append((new_key, v))
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec_dict)

